FROM token_usage tu
LEFT JOIN agent a ON tu.agent_id = a.id
LEFT JOIN model_config mc ON tu.model_config_id = mc.id
WHERE tu.tenant_id = #{tenantId}
AND tu.agent_id = #{agentId}
AND tu.usage_type = #{usageType}
AND tu.usage_date >= #{startDate}
AND tu.usage_date <= #{endDate}
