AND (a.agent_name LIKE CONCAT('%', #{keyword}, '%')
     OR mc.model_name LIKE CONCAT('%', #{keyword}, '%')
     OR mc.display_name LIKE CONCAT('%', #{keyword}, '%'))

choose.otherwise:
SELECT COUNT(*)
FROM token_usage tu
WHERE tu.tenant_id = #{tenantId}
